#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        MolarEnergy::new(v, MolarEnergyUnit::JoulePerMole),
        MolarEnergy::from_joules_per_mole(v)
    );
    assert_eq!(
        MolarEnergy::from_base(v).convert_to(MolarEnergyUnit::JoulePerMole),
        MolarEnergy::from_base(v).as_joules_per_mole()
    );
    assert_eq!(
        MolarEnergy::new(v, MolarEnergyUnit::KilojoulePerMole),
        MolarEnergy::from_kilojoules_per_mole(v)
    );
    assert_eq!(
        MolarEnergy::from_base(v).convert_to(MolarEnergyUnit::KilojoulePerMole),
        MolarEnergy::from_base(v).as_kilojoules_per_mole()
    );
    assert_eq!(
        MolarEnergy::new(v, MolarEnergyUnit::MegajoulePerMole),
        MolarEnergy::from_megajoules_per_mole(v)
    );
    assert_eq!(
        MolarEnergy::from_base(v).convert_to(MolarEnergyUnit::MegajoulePerMole),
        MolarEnergy::from_base(v).as_megajoules_per_mole()
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "J/mol".parse::<MolarEnergyUnit>(),
        Ok(MolarEnergyUnit::JoulePerMole)
    );
    assert_eq!(
        format!("2.5 {}", "J/mol").parse::<MolarEnergy>(),
        Ok(MolarEnergy::new(2.5, MolarEnergyUnit::JoulePerMole))
    );
    assert_eq!(
        "kJ/mol".parse::<MolarEnergyUnit>(),
        Ok(MolarEnergyUnit::KilojoulePerMole)
    );
    assert_eq!(
        format!("2.5 {}", "kJ/mol").parse::<MolarEnergy>(),
        Ok(MolarEnergy::new(2.5, MolarEnergyUnit::KilojoulePerMole))
    );
    assert_eq!(
        "MJ/mol".parse::<MolarEnergyUnit>(),
        Ok(MolarEnergyUnit::MegajoulePerMole)
    );
    assert_eq!(
        format!("2.5 {}", "MJ/mol").parse::<MolarEnergy>(),
        Ok(MolarEnergy::new(2.5, MolarEnergyUnit::MegajoulePerMole))
    );
    assert_eq!(
        "1 not-a-unit".parse::<MolarEnergy>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = MolarEnergy::from_base(6.0);
    let b = MolarEnergy::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = MolarEnergy::<i64>::from_base(7);
    let b = MolarEnergy::<i64>::from_base(2);
    assert_eq!(a + b, MolarEnergy::from_base(9));
    assert_eq!(a % b, MolarEnergy::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<MolarEnergy<i64>>(),
        MolarEnergy::from_base(9)
    );
}
